// shared/src/routine.ts: the types routineRun and its triggers share. Export them from shared/src/index.ts.
export type Stage = "shadow" | "drafts" | "normal";

/** One event that woke a routine. Every event with the same root cause joins one run (addTrigger). */
export type Trigger =
  | { kind: "github.workflow_run"; repo: string; runId: number; headSha: string; jobs: { name: string; firstError: string }[] }
  | { kind: "jira"; key: string }
  | { kind: "schedule"; name: string };

/** What a trigger passes to routineRun. charterSha pins the charter to one ai-agents commit. */
export interface RoutineRequest {
  routine: string; // the charter name, e.g. fe-ci-fixer
  charterSha: string;
  trigger?: Trigger; // schedules and the Jira poll start with a trigger; GitHub events arrive as addTrigger
}

/** The gate's answer before any VM: go, wait and look again later, or stop for good. */
export type GateVerdict =
  | { verdict: "go" }
  | { verdict: "wait"; reason: string; recheckMinutes: number }
  | { verdict: "stop"; reason: string };

/** The RoutineOutcome search attribute: G5-21's list, plus shadow and stopped (see the card's gaps). */
export type RoutineOutcome =
  | "merged" | "closed" | "rejected" | "failed" | "handed_off" | "not_needed" | "shadow" | "stopped";

// orchestrator/src/search-attributes.ts: typed keys for the routine search attributes (pure: workflows may import it).
// Register them on namespace ai-agents first. Agent, JiraKey and RunKind already exist; Routine, RoutineOutcome and
// Stage are new.
import { defineSearchAttributeKey, SearchAttributeType } from "@temporalio/common";

export const ROUTINE = defineSearchAttributeKey("Routine", SearchAttributeType.KEYWORD);
export const RUN_KIND = defineSearchAttributeKey("RunKind", SearchAttributeType.KEYWORD);
export const ROUTINE_OUTCOME = defineSearchAttributeKey("RoutineOutcome", SearchAttributeType.KEYWORD);
export const STAGE = defineSearchAttributeKey("Stage", SearchAttributeType.KEYWORD);

// orchestrator/src/routines/task-spec.ts: pure code (no I/O, no clock), so routineRun may call it inside the workflow.
import type { Charter, Trigger } from "@rhinohealth/ai-agents-shared";

/** The harness task for one routine run. workInSandbox writes it to /run/nova/task.json. */
export interface RoutineTask {
  job: "routine";
  routine: string;
  goal: string;
  done: string[];
  skills: string[];
  allowedPaths: string[];
  deniedPaths: string[];
  never: string[];
  model: string;
  effort: string;
  onFailedChecks?: string;
  setup?: string;
  triggers: Trigger[];
}

const describeTrigger = (t: Trigger): string => {
  switch (t.kind) {
    case "github.workflow_run":
      return `CI run ${t.runId} in ${t.repo} failed at ${t.headSha.slice(0, 7)}. ` +
        t.jobs.map((j) => `Job "${j.name}" first error: ${j.firstError}`).join(" ");
    case "jira":
      return `Jira ticket ${t.key}.`;
    case "schedule":
      return `Scheduled run ${t.name}.`;
  }
};

/** No maxTurns, no budget and no time limit: the charter's done list says when the work is finished. */
export const TaskSpec = {
  fromCharter: (charter: Charter, triggers: Trigger[]): RoutineTask => ({
    job: "routine",
    routine: charter.name,
    goal: [`Routine ${charter.name}.`, ...triggers.map(describeTrigger)].join("\n"),
    done: charter.done,
    skills: charter.skills,
    allowedPaths: charter.allowed_paths, // the harness hook refuses edits outside them; the git proxy checks again
    deniedPaths: charter.denied_paths ?? [],
    never: charter.never ?? [],
    model: charter.model.name,
    effort: charter.model.effort,
    onFailedChecks: charter.model.on_failed_checks,
    setup: charter.setup,
    triggers,
  }),
};

// orchestrator/src/activities/pre-run-gate.ts: the checks before any VM, in the ticket's order. Activities may do I/O.
import type { Charter, GateVerdict, Stage } from "@rhinohealth/ai-agents-shared";
import { readFlag } from "../flags.js";
import { mayOpenPr } from "./noise.js"; // G5-02

const STAGES: Stage[] = ["shadow", "drafts", "normal"];

/** The lower of the charter's stage and the override G5-15 writes. Read once, at the start of the run. */
export const effectiveStage = async (charter: Charter): Promise<Stage> => {
  const override = (await readFlag(`routine:${charter.name}:stage_override`))?.value as Stage | undefined;
  if (!override || !STAGES.includes(override)) return charter.stage;
  return STAGES[Math.min(STAGES.indexOf(charter.stage), STAGES.indexOf(override))] ?? "shadow";
};

export const preRunGate = async (charter: Charter, stage: Stage): Promise<GateVerdict> => {
  const killed = await readFlag(`agent:${charter.queue}:stopped`); // 1. the kill switch (G3-25)
  if (killed) return { verdict: "stop", reason: `kill switch: ${killed.reason}` };
  const paused = await readFlag(`routine:${charter.name}:paused`); // 2. paused by its owner or the breaker
  if (paused) return { verdict: "wait", reason: `${charter.name} is paused: ${paused.reason}`, recheckMinutes: 60 };
  const incident = charter.queue === "cifix" ? await readFlag("routines:fixers:paused") : null; // 3. incident mode
  if (incident) return { verdict: "wait", reason: `incident mode: ${incident.reason}`, recheckMinutes: 60 };
  if (stage === "shadow") return { verdict: "go" }; // shadow opens no PR, so rule 4 can't block it
  const pr = await mayOpenPr(charter.name, charter.repo ?? "RhinoHealth/fcp"); // 4. one open PR per routine
  if (pr.verdict === "wait") return { verdict: "wait", reason: pr.reason, recheckMinutes: 60 };
  return { verdict: "go" };
};

// orchestrator/src/routines/agent-for.ts: which agent (queue family) runs a routine, read from its charter.
import { loadCharter } from "./charter.js"; // G5-06

/** The ai-agents commit this worker was built from; triggers pin each run's charter to it. */
export const CHARTER_SHA = process.env.AI_AGENTS_SHA ?? "local";

/** fe-ci-fixer → cifix. The agent names the task queue (ai-agents-cifix), the VM slots and the kill switch. */
export const agentFor = async (routine: string): Promise<string> => (await loadCharter(routine, CHARTER_SHA)).queue;

export const queueFor = async (routine: string): Promise<string> => `ai-agents-${await agentFor(routine)}`;

// orchestrator/src/workflows/ship-pr.ts: the PR half of ticketToPr (scope judge, draft PR, Byte, findings, ready),
// shared by Nova and every routine. Until the G4 owner moves that code here, this placeholder fails loudly, and
// every routine stays in shadow, so no run reaches it.
import { ApplicationFailure } from "@temporalio/workflow";
import type { Charter, RoutineOutcome, RunOutcome, Stage } from "@rhinohealth/ai-agents-shared";

export interface ShipPrInput { charter: Charter; stage: Stage; run: RunOutcome }
export interface ShipPrResult { outcome: RoutineOutcome; prUrl?: string }

export async function shipPr(input: ShipPrInput): Promise<ShipPrResult> {
  throw ApplicationFailure.nonRetryable(`shipPr is not split out of ticketToPr yet; keep ${input.charter.name} in shadow`, "NeedsPerson");
}

// orchestrator/src/workflows/routine-run.ts: workflow code (deterministic: no Node APIs, no fetch, no clock for logic).
import {
  CancellationScope, condition, defineSignal, executeChild, isCancellation, setHandler, upsertSearchAttributes, workflowInfo,
} from "@temporalio/workflow";
import type { PlanDecision, RoutineOutcome, RoutineRequest, RunOutcome, Trigger } from "@rhinohealth/ai-agents-shared";
import { act, peopleApis } from "../policies.js"; // LONG preset: 7 days start-to-close, 2-minute heartbeats (G3-29)
import { TaskSpec } from "../routines/task-spec.js";
import { ROUTINE, ROUTINE_OUTCOME, RUN_KIND, STAGE } from "../search-attributes.js";
import { killed } from "./kill-switch.js";
import { shipPr } from "./ship-pr.js";
import { giveSlot, takeSlot } from "./with-slot.js";

export const addTrigger = defineSignal<[Trigger]>("addTrigger"); // a later event with the same root cause joins
export const decidePlan = defineSignal<[PlanDecision]>("decidePlan"); // handler comes with the bug fixers (G5-27)
export const stop = defineSignal<[by: string]>("stop"); // the kill switch's batch stop, or a person took the bug

export interface RoutineResult { outcome: RoutineOutcome; reason?: string; run?: RunOutcome; prUrl?: string }

export async function routineRun(req: RoutineRequest): Promise<RoutineResult> {
  const triggers: Trigger[] = req.trigger ? [req.trigger] : [];
  let stoppedBy: string | undefined;
  setHandler(addTrigger, (t) => void triggers.push(t));
  setHandler(stop, (by) => void (stoppedBy = by));
  const end = (outcome: RoutineOutcome, more: Omit<RoutineResult, "outcome"> = {}): RoutineResult => {
    upsertSearchAttributes([{ key: ROUTINE_OUTCOME, value: outcome }]); // G5-21's breaker reads it
    return { outcome, ...more };
  };
  const charter = await act.loadCharter(req.routine, req.charterSha);
  const stage = await act.effectiveStage(charter);
  upsertSearchAttributes([{ key: ROUTINE, value: charter.name }, { key: RUN_KIND, value: charter.queue }, { key: STAGE, value: stage }]);
  if (charter.gather_minutes) await condition(() => stoppedBy !== undefined, `${charter.gather_minutes} minutes`);
  for (;;) { // the gate: a run that must wait sleeps on a durable timer and never holds a VM
    if (stoppedBy) return end("stopped", { reason: `stopped by ${stoppedBy}` });
    const gate = await peopleApis.preRunGate(charter, stage);
    if (gate.verdict === "go") break;
    if (gate.verdict === "stop") return end("stopped", { reason: gate.reason });
    await condition(() => stoppedBy !== undefined, `${gate.recheckMinutes} minutes`);
  }
  const task = TaskSpec.fromCharter(charter, triggers);
  let run: RunOutcome | undefined;
  while (!run || run.state === "preempted") { // AWS took the Spot VM back: same step, fresh VM
    await takeSlot(charter.queue);
    const vm = await act.acquireSandbox({ runId: workflowInfo().runId, agent: charter.queue, ...charter.vm });
    const work = new CancellationScope();
    void condition(() => stoppedBy !== undefined).then(() => work.cancel()); // Stop also ends a step in progress
    try {
      run = await work.run(() => act.workInSandbox(vm, task));
    } catch (err) {
      if (!isCancellation(err)) throw err;
      return end("stopped", { reason: `stopped by ${stoppedBy}` });
    } finally {
      await CancellationScope.nonCancellable(() => act.releaseSandbox(vm));
      await giveSlot(charter.queue);
    }
  }
  if (run.state !== "done") return end("failed", { run });
  if (stage === "shadow") return end("shadow", { run }); // opens nothing; the weekly report reads Stage=shadow runs
  if ((await killed(charter.queue)) || stoppedBy) return end("stopped", { run });
  const shipped = await executeChild(shipPr, { args: [{ charter, stage, run }], workflowId: `${workflowInfo().workflowId}:pr` });
  return end(shipped.outcome, { run, prUrl: shipped.prUrl });
}

// orchestrator/test/workflows/routines.ts: the workflows the routineRun tests bundle.
export { slots } from "../../src/workflows/slots.js";
export { routineRun } from "../../src/workflows/routine-run.js";

// orchestrator/test/routine-run.test.ts: routineRun with fake activities on a local Temporal dev server.
import assert from "node:assert/strict";
import { after, before, beforeEach, test } from "node:test";
import { setTimeout as sleep } from "node:timers/promises";
import { fileURLToPath } from "node:url";
import { TestWorkflowEnvironment } from "@temporalio/testing";
import { Worker } from "@temporalio/worker";
import type { Charter, GateVerdict, RoutineRequest, Trigger } from "@rhinohealth/ai-agents-shared";
import { addTrigger, routineRun, stop } from "../src/workflows/routine-run.js";

const SEARCH_ATTRIBUTES = ["Agent", "Routine", "RunKind", "RoutineOutcome", "Stage"].flatMap((a) => ["--search-attribute", `${a}=Keyword`]);
const charter: Charter = {
  name: "fe-ci-fixer", stage: "shadow", trigger: { kind: "github.workflow_run" }, gather_minutes: 1, queue: "cifix",
  vm: { size: "lite", spot: true }, model: { name: "claude-opus-5-5", effort: "low" },
  allowed_paths: ["frontend/**"], skills: ["fix-ci"], done: ["npm run verify is green"],
};
const red = (runId: number): Trigger => ({ kind: "github.workflow_run", repo: "fcp", runId, headSha: "4b7e2a9", jobs: [] });
const req: RoutineRequest = { routine: "fe-ci-fixer", charterSha: "abc123", trigger: red(1) };
let calls: string[] = [];
let gate: GateVerdict = { verdict: "go" };
let env: TestWorkflowEnvironment, worker: Worker, running: Promise<void>;

before(async () => {
  env = await TestWorkflowEnvironment.createLocal({ server: { extraArgs: SEARCH_ATTRIBUTES } });
  worker = await Worker.create({
    connection: env.nativeConnection, taskQueue: "ai-agents-cifix",
    workflowsPath: fileURLToPath(new URL("./workflows/routines.ts", import.meta.url)),
    activities: {
      loadCharter: async (name: string) => ({ ...charter, gather_minutes: name === "no-gather" ? 0 : 1 }),
      effectiveStage: async () => charter.stage, preRunGate: async () => gate,
      agentStopped: async () => false, stillOpen: async (ids: string[]) => ids,
      acquireSandbox: async () => (calls.push("acquire"), { instanceId: "i-1", size: "lite", runId: "r1" }),
      workInSandbox: async (_vm: unknown, task: { triggers: Trigger[] }) => (calls.push(`work:${task.triggers.length}`), { state: "done" }),
      releaseSandbox: async () => void calls.push("release"),
    },
  });
  running = worker.run();
  await env.client.workflow.start("slots", { workflowId: "slots:cifix", taskQueue: "ai-agents-cifix", args: ["cifix"] });
});
beforeEach(() => void (calls = []));
after(async () => {
  worker.shutdown();
  await running;
  await env.teardown();
});

test("events in the gather window join one run, and shadow opens nothing", async () => {
  const run = await env.client.workflow.start(routineRun, { workflowId: "cifix:fcp:aaa", taskQueue: "ai-agents-cifix", args: [req] });
  await run.signal(addTrigger, red(2)); // 10:05: another push fails the same way
  await run.signal(addTrigger, red(3));
  assert.equal((await run.result()).outcome, "shadow"); // takes about a minute: the gather window
  assert.deepEqual(calls, ["acquire", "work:3", "release"]); // one VM for three events
});

test("a gate that says wait never claims a VM", async () => {
  gate = { verdict: "wait", reason: "incident mode", recheckMinutes: 60 };
  const run = await env.client.workflow.start(routineRun, {
    workflowId: "cifix:fcp:bbb", taskQueue: "ai-agents-cifix", args: [{ ...req, routine: "no-gather" }] });
  await sleep(2_000); // no gather window here: the run is parked at the gate by now
  await run.signal(stop, "sean");
  assert.equal((await run.result()).outcome, "stopped");
  assert.deepEqual(calls, []);
});
